import * as THREE from 'three';
import {advance,visibleBays} from './movement.js';
const $=id=>document.getElementById(id);
const renderer=new THREE.WebGLRenderer({canvas:$('world'),antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene();scene.background=new THREE.Color('#e6e0d4');scene.fog=new THREE.Fog('#e6e0d4',28,85);
const camera=new THREE.PerspectiveCamera(65,innerWidth/innerHeight,.1,120);camera.rotation.order='YXZ';
scene.add(new THREE.HemisphereLight(0xfff5dc,0x7b8075,2.5));const sun=new THREE.DirectionalLight(0xfff4dc,2);sun.position.set(0,5,4);scene.add(sun);
const materials={wall:new THREE.MeshStandardMaterial({color:'#eee9de',roughness:.9}),floor:new THREE.MeshStandardMaterial({color:'#a99d84',roughness:.55}),frame:new THREE.MeshStandardMaterial({color:'#514b3c',metalness:.5,roughness:.4}),trim:new THREE.MeshStandardMaterial({color:'#cec5b3'}),light:new THREE.MeshBasicMaterial({color:'#fff9e8'})};
let artworks=[],distance=0,yaw=0,pitch=0,walking=false,auto=false,entered=false,drag=null,last=performance.now();
const bays=new Map(),textures=new Map(),loader=new THREE.TextureLoader(),ray=new THREE.Raycaster(),pointer=new THREE.Vector2();
const date=a=>new Date(a.createdAt).toLocaleString('en-AU',{timeZone:'Australia/Brisbane',dateStyle:'long',timeStyle:'medium'})+' AEST';
function box(g,w,h,d,x,y,z,mat){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);g.add(m);return m}
function placard(a,index){const c=document.createElement('canvas');c.width=1024;c.height=320;const ctx=c.getContext('2d');ctx.fillStyle='#f9f6ed';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#303b34';ctx.font='24px Arial';ctx.fillText('CODEX / ORIGINAL WORK '+String(index+1).padStart(4,'0'),38,52);ctx.font='38px Georgia';const words=a.title.split(' ');let line='',y=115;for(const word of words){if(ctx.measureText(line+word).width>940){ctx.fillText(line,38,y);y+=44;line='';}line+=word+' ';}ctx.fillText(line,38,y);ctx.font='25px Arial';ctx.fillText(date(a),38,245);ctx.font='20px Arial';ctx.fillText('AI-generated original · Click canvas to inspect',38,289);return new THREE.CanvasTexture(c)}
function addArt(g,a,index,side,z){let tex=textures.get(a.image);if(!tex){tex=loader.load(a.image);tex.colorSpace=THREE.SRGBColorSpace;textures.set(a.image,tex)}const mount=new THREE.Group();mount.position.set(side*3.86,2.35,z);mount.rotation.y=side===-1?Math.PI/2:-Math.PI/2;g.add(mount);box(mount,2.9,2.9,.1,0,0,0,materials.frame);const art=new THREE.Mesh(new THREE.PlaneGeometry(2.7,2.7),new THREE.MeshBasicMaterial({map:tex}));art.position.z=.061;art.userData.art=a;art.userData.index=index;mount.add(art);const label=new THREE.Mesh(new THREE.PlaneGeometry(2.15,.67),new THREE.MeshBasicMaterial({map:placard(a,index)}));label.position.set(0,-1.94,.07);mount.add(label)}
function makeBay(n){const g=new THREE.Group();g.position.z=-n*9;scene.add(g);box(g,8,.15,9,0,-.075,-4.5,materials.floor);box(g,.2,5,9,-4.1,2.5,-4.5,materials.wall);box(g,.2,5,9,4.1,2.5,-4.5,materials.wall);box(g,8,.15,9,0,5,-4.5,materials.wall);for(const s of [-1,1]){box(g,.12,.16,9,s*3.96,.15,-4.5,materials.trim);box(g,.16,5,.2,s*3.95,2.5,-8.95,materials.trim)}box(g,1.8,.04,3,0,4.88,-4.5,materials.light);for(let i=0;i<6;i++)box(g,8,.012,.02,0,.009,-i*1.5,materials.trim);if(artworks.length){for(let k=0;k<2;k++){const index=(n*2+k)%artworks.length;addArt(g,artworks[index],index,k===0?-1:1,-4.5)}}return g}
function dispose(g){g.traverse(m=>{if(m.geometry)m.geometry.dispose();if(m.material&&!Object.values(materials).includes(m.material)){if(m.material.map&&!textures.has(m.userData.art?.image))m.material.map.dispose();m.material.dispose()}});scene.remove(g)}
function refreshBays(reset=false){const wanted=new Set(visibleBays(distance));for(const [n,g] of bays)if(reset||!wanted.has(n)){dispose(g);bays.delete(n)}for(const n of wanted)if(!bays.has(n))bays.set(n,makeBay(n))}
async function refreshArt(){try{const r=await fetch('artworks.json?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('Collection unavailable');const next=await r.json();if(JSON.stringify(next)!==JSON.stringify(artworks)){artworks=next;refreshBays(true)}$('count').textContent=artworks.length+' original works · always growing';}catch(e){$('hint').textContent='Collection update unavailable. Retrying shortly.'}}
function openArt(hit){walking=false;auto=false;$('stroll').textContent='Stroll';document.exitPointerLock?.();const a=hit.object.userData.art;$('full-art').src=a.image;$('full-art').alt=a.title;$('art-title').textContent=a.title;$('art-description').textContent=a.description;$('art-date').textContent=date(a);$('art-number').textContent='WORK '+String(hit.object.userData.index+1).padStart(4,'0');$('art-dialog').showModal()}
function pick(x,y){pointer.set(x/innerWidth*2-1,-y/innerHeight*2+1);ray.setFromCamera(pointer,camera);return ray.intersectObjects(scene.children,true).find(h=>h.object.userData.art&&h.distance<8)}
$('enter').onclick=()=>{entered=true;$('welcome').hidden=true;$('controls').hidden=false;$('reticle').hidden=false;$('world').requestPointerLock?.()};
$('close').onclick=()=>{$('art-dialog').close()};
addEventListener('keydown',e=>{if(['KeyW','ArrowUp','Space'].includes(e.code))e.preventDefault();if(!entered||$('art-dialog').open)return;if(e.code==='KeyW'||e.code==='ArrowUp')walking=true;if(e.code==='Space'&&!e.repeat){auto=!auto;$('stroll').textContent=auto?'Pause':'Stroll'}});
addEventListener('keyup',e=>{if(e.code==='KeyW'||e.code==='ArrowUp')walking=false});addEventListener('blur',()=>{walking=false;auto=false});
$('stroll').onclick=()=>{auto=!auto;$('stroll').textContent=auto?'Pause':'Stroll'};
$('walk').onpointerdown=e=>{walking=true;e.currentTarget.setPointerCapture(e.pointerId)};$('walk').onpointerup=$('walk').onpointercancel=()=>walking=false;
$('world').onpointerdown=e=>{if(entered)drag={x:e.clientX,y:e.clientY,moved:0}};
addEventListener('pointermove',e=>{if(!entered||$('art-dialog').open)return;let dx=0,dy=0;if(document.pointerLockElement){dx=e.movementX;dy=e.movementY}else if(drag){dx=e.clientX-drag.x;dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY}if(drag)drag.moved+=Math.abs(dx)+Math.abs(dy);yaw-=dx*.0025;pitch=THREE.MathUtils.clamp(pitch-dy*.0025,-1.45,1.45)});
$('world').onpointerup=e=>{if(!entered)return;if(!drag||drag.moved<8){const locked=!!document.pointerLockElement;const hit=pick(locked?innerWidth/2:e.clientX,locked?innerHeight/2:e.clientY);if(hit)openArt(hit);else $('world').requestPointerLock?.()}drag=null};
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
refreshBays();await refreshArt();setInterval(refreshArt,30000);
function frame(now){distance=advance(distance,(now-last)/1000,entered&&!$('art-dialog').open&&(walking||auto));last=now;camera.position.set(0,1.7,2-distance);camera.rotation.set(pitch,yaw,0);refreshBays();$('distance').textContent=Math.floor(distance)+' m';if(entered&&!$('art-dialog').open){const hit=pick(innerWidth/2,innerHeight/2);$('hint').textContent=hit?'Click to study “'+hit.object.userData.art.title+'”':''}renderer.render(scene,camera);requestAnimationFrame(frame)}requestAnimationFrame(frame);
